import{_ as o,r as s,o as p,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Migrations & Seeding - October CMS - 4.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Migration Structure","slug":"migration-structure","link":"#migration-structure","children":[]},{"level":2,"title":"Creating Tables","slug":"creating-tables","link":"#creating-tables","children":[{"level":3,"title":"Connection & Storage Engine","slug":"connection-storage-engine","link":"#connection-storage-engine","children":[]}]},{"level":2,"title":"Renaming / Dropping Tables","slug":"renaming-dropping-tables","link":"#renaming-dropping-tables","children":[]},{"level":2,"title":"Creating Columns","slug":"creating-columns","link":"#creating-columns","children":[{"level":3,"title":"Available Column Types","slug":"available-column-types","link":"#available-column-types","children":[]},{"level":3,"title":"Column Modifiers","slug":"column-modifiers","link":"#column-modifiers","children":[]}]},{"level":2,"title":"Modifying Columns","slug":"modifying-columns","link":"#modifying-columns","children":[{"level":3,"title":"Renaming Columns","slug":"renaming-columns","link":"#renaming-columns","children":[]},{"level":3,"title":"Dropping Columns","slug":"dropping-columns","link":"#dropping-columns","children":[]}]},{"level":2,"title":"Creating Indexes","slug":"creating-indexes","link":"#creating-indexes","children":[{"level":4,"title":"Available Index Types","slug":"available-index-types","link":"#available-index-types","children":[]},{"level":3,"title":"Renaming Indexes","slug":"renaming-indexes","link":"#renaming-indexes","children":[]},{"level":3,"title":"Dropping Indexes","slug":"dropping-indexes","link":"#dropping-indexes","children":[]},{"level":3,"title":"Foreign Key Constraints","slug":"foreign-key-constraints","link":"#foreign-key-constraints","children":[]}]},{"level":2,"title":"Seeder Structure","slug":"seeder-structure","link":"#seeder-structure","children":[{"level":3,"title":"Calling Additional Seeders","slug":"calling-additional-seeders","link":"#calling-additional-seeders","children":[]}]}],"relativePath":"4.x/extend/database/structure.md","filePath":"4.x/extend/database/structure.md"}'),u={name:"4.x/extend/database/structure.md"};function r(d,n,k,g,h,m){const t=s("pre-heading"),e=s("post-heading");return p(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"Migrations & Seeding",-1)),a(e),n[1]||(n[1]=i(`<p>Migrations and seed files allow you to build, modify and populate database tables. They are primarily used by a <a href="./../system/plugins.html">plugin update file</a> and are paired with the version history of a plugin. All classes are stored in the <code>updates</code> directory of a plugin. Migrations should tell a story about your database history and this story can be played both forwards and backwards to build up and tear down the tables.</p><p>You may generate a migration file using the command line scaffolding tool. The first argument specifies the author and plugin name. The second argument specifies the migration name.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:migration Acme.Blog CreatePostsTable
</code></pre></div><h2 id="migration-structure"><a href="#migration-structure" class="header-anchor">#</a> Migration Structure</h2><p>A migration file should define a class that extends the <code>October\\Rain\\Database\\Updates\\Migration</code> class and contains two methods: <code>up</code> and <code>down</code>. The <code>up</code> method is used to add new tables, columns, or indexes to your database, while the <code>down</code> method should simply reverse the operations performed by the <code>up</code> method. Within both of these methods you may use the schema builder to expressively create and modify tables. For example, let&#39;s look at a sample migration that creates a <code>october_blog_posts</code> table:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Schema<span class="token punctuation">\\</span>Blueprint</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Updates<span class="token punctuation">\\</span>Migration</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token keyword">class</span> <span class="token class-name-definition class-name">extends</span> <span class="token class-name">Migration</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">up</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;october_blog_posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span>
        <span class="token punctuation">{</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">increments</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;slug&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">text</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;excerpt&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">text</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;content&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">timestamp</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;published_at&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">boolean</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_published&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">default</span><span class="token punctuation">(</span><span class="token constant boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">timestamps</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">down</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">drop</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;october_blog_posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="creating-tables"><a href="#creating-tables" class="header-anchor">#</a> Creating Tables</h2><div class="custom-block aside"><p>When creating the table, you may use any of the schema builder&#39;s column methods to define the table&#39;s columns (see below).</p></div><p>To create a new database table, use the <code>create</code> method on the <code>Schema</code> facade. The <code>create</code> method accepts two arguments. The first is the name of the table, while the second is a <code>Closure</code> which receives an object used to define the new table.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">increments</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may check for the existence of a table or column using the <code>hasTable</code> and <code>hasColumn</code> methods.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">hasTable</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">hasColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="connection-storage-engine"><a href="#connection-storage-engine" class="header-anchor">#</a> Connection &amp; Storage Engine</h3><p>If you want to perform a schema operation on a database connection that is not your default connection, use the <code>connection</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">increments</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To set the storage engine for a table, set the <code>engine</code> property on the schema builder.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token property">engine</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;InnoDB&#39;</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">increments</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="renaming-dropping-tables"><a href="#renaming-dropping-tables" class="header-anchor">#</a> Renaming / Dropping Tables</h2><p>To rename an existing database table, use the <code>rename</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">rename</span><span class="token punctuation">(</span><span class="token variable">$from</span><span class="token punctuation">,</span> <span class="token variable">$to</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To drop an existing table, you may use the <code>drop</code> or <code>dropIfExists</code> methods.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">drop</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">dropIfExists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="creating-columns"><a href="#creating-columns" class="header-anchor">#</a> Creating Columns</h2><p>To update an existing table, we will use the <code>table</code> method on the <code>Schema</code> facade. Like the <code>create</code> method, the <code>table</code> method accepts two arguments, the name of the table and a <code>Closure</code> that receives an object we can use to add columns to the table:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="available-column-types"><a href="#available-column-types" class="header-anchor">#</a> Available Column Types</h3><p>Of course, the schema builder contains a variety of column types that you may use when building your tables.</p><div class="table"><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>$table-&gt;bigIncrements(&#39;id&#39;);</code></td><td>Incrementing ID (primary key) using a &quot;UNSIGNED BIG INTEGER&quot; equivalent.</td></tr><tr><td><code>$table-&gt;bigInteger(&#39;votes&#39;);</code></td><td>BIGINT equivalent for the database.</td></tr><tr><td><code>$table-&gt;binary(&#39;data&#39;);</code></td><td>BLOB equivalent for the database.</td></tr><tr><td><code>$table-&gt;boolean(&#39;confirmed&#39;);</code></td><td>BOOLEAN equivalent for the database.</td></tr><tr><td><code>$table-&gt;char(&#39;name&#39;, 4);</code></td><td>CHAR equivalent with a length.</td></tr><tr><td><code>$table-&gt;date(&#39;created_at&#39;);</code></td><td>DATE equivalent for the database.</td></tr><tr><td><code>$table-&gt;dateTime(&#39;created_at&#39;);</code></td><td>DATETIME equivalent for the database.</td></tr><tr><td><code>$table-&gt;decimal(&#39;amount&#39;, 5, 2);</code></td><td>DECIMAL equivalent with a precision and scale.</td></tr><tr><td><code>$table-&gt;double(&#39;column&#39;, 15, 8);</code></td><td>DOUBLE equivalent with precision, 15 digits in total and 8 after the decimal point.</td></tr><tr><td><code>$table-&gt;enum(&#39;choices&#39;, [&#39;foo&#39;, &#39;bar&#39;]);</code></td><td>ENUM equivalent for the database.</td></tr><tr><td><code>$table-&gt;float(&#39;amount&#39;);</code></td><td>FLOAT equivalent for the database.</td></tr><tr><td><code>$table-&gt;increments(&#39;id&#39;);</code></td><td>Incrementing ID (primary key) using a &quot;UNSIGNED INTEGER&quot; equivalent.</td></tr><tr><td><code>$table-&gt;integer(&#39;votes&#39;);</code></td><td>INTEGER equivalent for the database.</td></tr><tr><td><code>$table-&gt;json(&#39;options&#39;);</code></td><td>JSON equivalent for the database.</td></tr><tr><td><code>$table-&gt;jsonb(&#39;options&#39;);</code></td><td>JSONB equivalent for the database.</td></tr><tr><td><code>$table-&gt;longText(&#39;description&#39;);</code></td><td>LONGTEXT equivalent for the database.</td></tr><tr><td><code>$table-&gt;mediumInteger(&#39;numbers&#39;);</code></td><td>MEDIUMINT equivalent for the database.</td></tr><tr><td><code>$table-&gt;mediumText(&#39;description&#39;);</code></td><td>MEDIUMTEXT equivalent for the database.</td></tr><tr><td><code>$table-&gt;morphs(&#39;taggable&#39;);</code></td><td>Adds INTEGER <code>taggable_id</code> and STRING <code>taggable_type</code>.</td></tr><tr><td><code>$table-&gt;nullableTimestamps();</code></td><td>Same as <code>timestamps()</code>, except allows NULLs.</td></tr><tr><td><code>$table-&gt;rememberToken();</code></td><td>Adds <code>remember_token</code> as VARCHAR(100) NULL.</td></tr><tr><td><code>$table-&gt;smallInteger(&#39;votes&#39;);</code></td><td>SMALLINT equivalent for the database.</td></tr><tr><td><code>$table-&gt;softDeletes();</code></td><td>Adds <code>deleted_at</code> column for soft deletes.</td></tr><tr><td><code>$table-&gt;string(&#39;email&#39;);</code></td><td>VARCHAR equivalent column.</td></tr><tr><td><code>$table-&gt;string(&#39;name&#39;, 100);</code></td><td>VARCHAR equivalent with a length.</td></tr><tr><td><code>$table-&gt;text(&#39;description&#39;);</code></td><td>TEXT equivalent for the database.</td></tr><tr><td><code>$table-&gt;time(&#39;sunrise&#39;);</code></td><td>TIME equivalent for the database.</td></tr><tr><td><code>$table-&gt;tinyInteger(&#39;numbers&#39;);</code></td><td>TINYINT equivalent for the database.</td></tr><tr><td><code>$table-&gt;timestamp(&#39;added_on&#39;);</code></td><td>TIMESTAMP equivalent for the database.</td></tr><tr><td><code>$table-&gt;timestamps();</code></td><td>Adds <code>created_at</code> and <code>updated_at</code> columns.</td></tr></tbody></table></div><h3 id="column-modifiers"><a href="#column-modifiers" class="header-anchor">#</a> Column Modifiers</h3><p>In addition to the column types listed above, there are several other column &quot;modifiers&quot; which you may use while adding the column. For example, to make the column &quot;nullable&quot;, you may use the <code>nullable</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Below is a list of all the available column modifiers. This list does not include the index modifiers.</p><div class="table"><table tabindex="0"><thead><tr><th>Modifier</th><th>Description</th></tr></thead><tbody><tr><td><code>-&gt;nullable()</code></td><td>Allow NULL values to be inserted into the column</td></tr><tr><td><code>-&gt;default($value)</code></td><td>Specify a &quot;default&quot; value for the column</td></tr><tr><td><code>-&gt;unsigned()</code></td><td>Set <code>integer</code> columns to <code>UNSIGNED</code></td></tr><tr><td><code>-&gt;first()</code></td><td>Place the column &quot;first&quot; in the table (MySQL Only)</td></tr><tr><td><code>-&gt;after(&#39;column&#39;)</code></td><td>Place the column &quot;after&quot; another column (MySQL Only)</td></tr><tr><td><code>-&gt;comment(&#39;my comment&#39;)</code></td><td>Add a comment to a column (MySQL Only)</td></tr></tbody></table></div><h2 id="modifying-columns"><a href="#modifying-columns" class="header-anchor">#</a> Modifying Columns</h2><p>The <code>change</code> method allows you to modify an existing column to a new type, or modify the column&#39;s attributes. For example, you may wish to increase the size of a string column. To see the <code>change</code> method in action, let&#39;s increase the size of the <code>name</code> column from 25 to 50.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">change</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>We could also modify a column to be nullable:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">change</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="renaming-columns"><a href="#renaming-columns" class="header-anchor">#</a> Renaming Columns</h3><p>To rename a column, you may use the <code>renameColumn</code> method on the Schema builder.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">renameColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;from&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;to&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Renaming columns in a table with a <code>enum</code> column is not currently supported.</p></div><h3 id="dropping-columns"><a href="#dropping-columns" class="header-anchor">#</a> Dropping Columns</h3><p>To drop a column, use the <code>dropColumn</code> method on the Schema builder.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">dropColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may drop multiple columns from a table by passing an array of column names to the <code>dropColumn</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">dropColumn</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;avatar&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;location&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="creating-indexes"><a href="#creating-indexes" class="header-anchor">#</a> Creating Indexes</h2><p>The schema builder supports several types of indexes. First, let&#39;s look at an example that specifies a column&#39;s values should be unique. To create the index, we can simply chain the <code>unique</code> method onto the column definition.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unique</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Alternatively, you may create the index after defining the column. For example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">unique</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may even pass an array of columns to an index method to create a compound index.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;created_at&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>In most cases you should specify a name for the index manually as the second argument, to avoid the system automatically generating one that is too long.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;created_at&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;account_created&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="available-index-types"><a href="#available-index-types" class="header-anchor">#</a> Available Index Types</h4><div class="table"><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>$table-&gt;primary(&#39;id&#39;);</code></td><td>Add a primary key.</td></tr><tr><td><code>$table-&gt;primary([&#39;first&#39;, &#39;last&#39;]);</code></td><td>Add composite keys.</td></tr><tr><td><code>$table-&gt;unique(&#39;email&#39;);</code></td><td>Add a unique index.</td></tr><tr><td><code>$table-&gt;index(&#39;state&#39;);</code></td><td>Add a basic index.</td></tr></tbody></table></div><h3 id="renaming-indexes"><a href="#renaming-indexes" class="header-anchor">#</a> Renaming Indexes</h3><p>To rename an index, use the <code>renameIndex</code> method provided by the schema builder blueprint. This method accepts the current index name as its first argument and the desired name as its second argument.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">renameIndex</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;from&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;to&#39;</span><span class="token punctuation">)</span>
</code></pre></div><h3 id="dropping-indexes"><a href="#dropping-indexes" class="header-anchor">#</a> Dropping Indexes</h3><p>To drop an index, you must specify the index&#39;s name. If no name was specified manually, the system will automatically generate one, simply concatenate the table name, the name of the indexed column, and the index type. Here are some examples:</p><div class="table"><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>$table-&gt;dropPrimary(&#39;users_id_primary&#39;);</code></td><td>Drop a primary key from the &quot;users&quot; table.</td></tr><tr><td><code>$table-&gt;dropUnique(&#39;users_email_unique&#39;);</code></td><td>Drop a unique index from the &quot;users&quot; table.</td></tr><tr><td><code>$table-&gt;dropIndex(&#39;geo_state_index&#39;);</code></td><td>Drop a basic index from the &quot;geo&quot; table.</td></tr></tbody></table></div><h3 id="foreign-key-constraints"><a href="#foreign-key-constraints" class="header-anchor">#</a> Foreign Key Constraints</h3><p>There is also support for creating foreign key constraints, which are used to force referential integrity at the database level. For example, let&#39;s define a <code>user_id</code> column on the <code>posts</code> table that references the <code>id</code> column on a <code>users</code> table:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unsigned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">foreign</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">references</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>As before, you may specify a name for the constraint manually by passing a second argument to the <code>foreign</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">foreign</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;user_foreign&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">references</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also specify the desired action for the &quot;on delete&quot; and &quot;on update&quot; properties of the constraint:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">foreign</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">references</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">onDelete</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cascade&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To drop a foreign key, you may use the <code>dropForeign</code> method. Foreign key constraints use the same naming convention as indexes. So, if one is not specified manually, we will concatenate the table name and the columns in the constraint then suffix the name with &quot;_foreign&quot;:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">dropForeign</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts_user_id_foreign&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="seeder-structure"><a href="#seeder-structure" class="header-anchor">#</a> Seeder Structure</h2><p>Like migration files, a seeder class only contains one method by default called <code>run</code> and should extend the <code>Seeder</code> class. The <code>run</code> method is called when the update process is executed. Within this method, you may insert data into your database however you wish. You may use the <a href="./query.html">query builder</a> to manually insert data or you may use your <a href="./model.html">model classes</a>. In the example below, we&#39;ll create a new user using the <code>User</code> model inside the <code>run</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Users<span class="token punctuation">\\</span>Updates</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Seeder</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Acme<span class="token punctuation">\\</span>Users<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">SeedUsersTable</span> <span class="token keyword">extends</span> <span class="token class-name">Seeder</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">run</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;user@example.tld&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;login&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;user&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;password123&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;password_confirmation&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;password123&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;first_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Actual&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;last_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Person&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;is_activated&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
        <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</span></code></pre></div><p>Alternatively, the same can be achieved using the <code>Db::table</code> <a href="./query.html">query builder</a> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">run</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">insert</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;user@example.tld&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;login&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;user&#39;</span><span class="token punctuation">,</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="calling-additional-seeders"><a href="#calling-additional-seeders" class="header-anchor">#</a> Calling Additional Seeders</h3><p>Within the <code>DatabaseSeeder</code> class, you may use the <code>call</code> method to execute additional seed classes. Using the <code>call</code> method allows you to break up your database seeding into multiple files so that no single seeder class becomes overwhelmingly large. Simply pass the name of the seeder class you wish to run.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">run</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Users<span class="token punctuation">\\</span>Updates<span class="token punctuation">\\</span>UserTableSeeder</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Users<span class="token punctuation">\\</span>Updates<span class="token punctuation">\\</span>PostsTableSeeder</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Users<span class="token punctuation">\\</span>Updates<span class="token punctuation">\\</span>CommentsTableSeeder</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,81))])}const y=o(u,[["render",r]]);export{f as __pageData,y as default};
